启动入口见 dwm 配置与美化 中的 ~/.xinitrc——切到 exec i3 即可，i3 自身无 autostart 需求（在配置内 exec 启动程序）。
i3blocks 配置**~/.config/i3blocks/config**：
# i3blocks configuration fileseparator_block_width=15[weather]command=~/.config/i3blocks/weatherinterval=1800[volume]command=~/.config/i3blocks/volumeinterval=2[wireless]command=~/.config/i3blocks/wirelessinterval=60[memory]command=~/.config/i3blocks/memoryinterval=10[weekday]command=~/.config/i3blocks/weekdayinterval=300[tztime]command=~/.config/i3blocks/tztimeinterval=60

各 block 脚本**~/.config/i3blocks/weather**：
#!/bin/sh# i3blocks weather block - wttr.inWEATHER=$(curl -s &quot;wttr.in/Beijing?format=%t+%C&quot; 2&gt;/dev/null)if [ -n &quot;$WEATHER&quot; ]; then    echo &quot;$WEATHER&quot;    echo &quot;$WEATHER&quot;    echo &quot;#89b4fa&quot;else    echo &quot;--&quot;    echo &quot;--&quot;    echo &quot;#666666&quot;fi

**~/.config/i3blocks/volume**：
#!/bin/bashVOLUME=$(pactl get-sink-volume @DEFAULT_SINK@ | grep -oP &#x27;\d+%&#x27; | head -1 | tr -d &#x27;%&#x27;)MUTE=$(pactl get-sink-mute @DEFAULT_SINK@ | grep -oP &#x27;yes|no&#x27;)if [ &quot;$MUTE&quot; = &quot;yes&quot; ]; then    ICON=&quot;静&quot;    COLOR=&quot;#666666&quot;elif [ &quot;$VOLUME&quot; -ge 70 ]; then    ICON=&quot;高&quot;    COLOR=&quot;#aaffaa&quot;elif [ &quot;$VOLUME&quot; -ge 30 ]; then    ICON=&quot;中&quot;    COLOR=&quot;#ffffaa&quot;else    ICON=&quot;低&quot;    COLOR=&quot;#ffaaaa&quot;fiecho &quot;$ICON $&#123;VOLUME&#125;%&quot;echo &quot;$ICON $&#123;VOLUME&#125;%&quot;echo &quot;$COLOR&quot;

**~/.config/i3blocks/wireless**：
#!/bin/bashIFACE=$(ip route | awk &#x27;/default/ &#123;print $5&#125;&#x27; | head -1)if [ -z &quot;$IFACE&quot; ]; then    echo &quot;无网络&quot;    echo &quot;无网络&quot;    echo &quot;#ff6666&quot;    exit 0fiIP=$(ip -4 addr show &quot;$IFACE&quot; | grep -oP &#x27;inet \K[\d.]+&#x27;)ESSID=$(nmcli -t -f active,ssid dev wifi 2&gt;/dev/null | awk -F: &#x27;$1==&quot;yes&quot;&#123;print $2&#125;&#x27;)if [ -n &quot;$ESSID&quot; ]; then    echo &quot;$&#123;ESSID&#125; $&#123;IP&#125;&quot;    echo &quot;$&#123;ESSID&#125; $&#123;IP&#125;&quot;else    echo &quot;$&#123;IP&#125;&quot;    echo &quot;$&#123;IP&#125;&quot;fiecho &quot;#aaffaa&quot;

**~/.config/i3blocks/memory**：
#!/bin/bashread -r total used free &lt;&lt;&lt; &quot;$(free -h | awk &#x27;/Mem:/&#123;print $2, $3, $7&#125;&#x27;)&quot;echo &quot;M: $used / $total&quot;echo &quot;M: $used / $total&quot;

**~/.config/i3blocks/weekday**：
#!/bin/bashDAY=$(date +%u)case $DAY in    1) TEXT=&quot;一&quot; ;;    2) TEXT=&quot;二&quot; ;;    3) TEXT=&quot;三&quot; ;;    4) TEXT=&quot;四&quot; ;;    5) TEXT=&quot;五&quot; ;;    6) TEXT=&quot;六&quot; ;;    7) TEXT=&quot;日&quot; ;;esacecho &quot;$TEXT&quot;echo &quot;$TEXT&quot;

**~/.config/i3blocks/tztime**：
#!/bin/bashDATETIME=$(date &quot;+%m-%d %H:%M&quot;)echo &quot;$DATETIME&quot;echo &quot;$DATETIME&quot;


天气接口 wttr.in/Beijing 中的城市可按需替换。
